import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.SetActorLink{EntityLink: protocol.EntityLink{RiddenEntityUniqueID: -1, RiderEntityUniqueID: 300,
#   Type: protocol.EntityLinkPassenger, Immediate: false, RiderInitiated: true, VehicleAngularVelocity: -2.5}}
GOLDEN = bytes.fromhex("01d804020001000020c0")

# generated by gophertunnel b8bd735:
# packet.SetActorLink{EntityLink: protocol.EntityLink{RiddenEntityUniqueID: 4294967296}}
WIDE = bytes.fromhex("80808080200000000000000000")

GOLDENS = [
    pytest.param(
        v2225.SetActorLinkPacket(
            link=v2225.ActorLink(
                a=-1,
                b=300,
                type=v2225.ActorLinkType.PASSENGER,
                immediate=False,
                passenger_initiated=True,
                vehicle_angular_velocity=-2.5,
            )
        ),
        GOLDEN,
        id="passenger",
    ),
    pytest.param(
        v2225.SetActorLinkPacket(
            link=v2225.ActorLink(
                a=4294967296,
                b=0,
                type=v2225.ActorLinkType.NONE,
                immediate=False,
                passenger_initiated=False,
                vehicle_angular_velocity=0.0,
            )
        ),
        WIDE,
        id="wide-target-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_set_actor_link_is_packet_41(version):
    assert version.PACKETS[41] is version.SetActorLinkPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_actor_link_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_set_actor_link_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
